function renderPostBatchRefreshFailures() {
  const failures = Array.isArray(state.postBatchRefreshFailures) ? state.postBatchRefreshFailures : [];
  if (!failures.length) return "";
  return `
    <section class="panel" id="postBatchRefreshFailuresPanel">
      <div class="section-head">
        <h3>批量刷新失败明细</h3>
        <div class="actions">
          <button class="ghost js-retry-failed-post-refresh" type="button">重试失败项</button>
          <button class="ghost js-clear-post-refresh-failures" type="button">清空</button>
        </div>
      </div>
      <ul style="margin:0;padding-left:18px;color:#7a1f17;">
        ${failures.map((entry) => `<li>${escapeHtml(entry.title || entry.id || "未知作品")}：${escapeHtml(entry.message || entry.reason || "抓取失败")}</li>`).join("")}
      </ul>
    </section>
  `;
}

function getPostMonitorDateRangeParams() {
  const params = new URLSearchParams();
  if (state.postMonitorMode === "week") {
    const dates = getDatesInWeek(state.postMonitorWeek);
    if (dates.length) {
      params.set("from", dates[0]);
      params.set("to", dates[dates.length - 1]);
    }
  } else if (state.postMonitorMode === "month") {
    const dates = getMonthDates(state.postMonitorMonth);
    if (dates.length) {
      params.set("from", dates[0]);
      params.set("to", dates[dates.length - 1]);
    }
  } else if (state.postMonitorDate) {
    params.set("from", state.postMonitorDate);
    params.set("to", state.postMonitorDate);
  }
  return params;
}

