function renderPostBulkImportDialog() {
  if (!state.postBulkImportOpen) return "";
  const result = state.postBulkImportResult;
  const rawErrors = Array.isArray(result?.errors) ? result.errors : Array.isArray(result?.failedRows) ? result.failedRows : [];
  const failedRows = rawErrors.slice(0, 50);
  const failedCount = Number(result?.fail ?? result?.failed ?? 0);
  const resultBlock = result ? `
    <div class="post-bulk-import-result" style="margin-top:12px;border-top:1px solid #eee;padding-top:10px;">
      <div style="font-size:14px;color:#333;margin-bottom:6px;">
        共 <strong>${Number(result.total || 0)}</strong> 行，成功
        <strong style="color:#16a34a;">${Number(result.success || 0)}</strong>，失败
        <strong style="color:#c0392b;">${failedCount}</strong>
      </div>
      ${failedRows.length ? `
        ${result.errorFileUrl ? `<p style="margin:0 0 6px;"><a href="${result.errorFileUrl}" target="_blank" rel="noopener">下载失败行错误文件</a></p>` : ""}
        <div style="font-size:12px;color:#666;margin-bottom:4px;">失败明细（前 ${failedRows.length} 条）：</div>
        <ul class="post-bulk-import-failed-list" style="max-height:200px;overflow:auto;margin:0;padding:6px 12px;background:#fdecea;border:1px solid #f5b7b1;border-radius:6px;list-style:disc;">
          ${failedRows.map((row) => `<li style="font-size:12px;color:#7a1f17;line-height:1.6;"><strong>第 ${Number(row?.row ?? row?.rowIndex ?? 0)} 行</strong>：${escapeHtml(String(row?.reason || row?.message || "未知错误"))}<div style="color:#9b3a31;word-break:break-all;">${escapeHtml(String(row?.raw || ""))}</div></li>`).join("")}
        </ul>
      ` : ""}
    </div>
  ` : "";
  return `
    <div class="supervisor-dialog-layer">
      <div class="supervisor-dialog-backdrop js-close-post-bulk-import"></div>
      <div class="supervisor-dialog" role="dialog" aria-modal="true" aria-label="批量导入作品" style="max-width:720px;">
        <div class="supervisor-dialog-header">
          <h3>批量导入作品</h3>
          <p>支持下载模板后上传 xlsx/csv，也支持从 Excel 复制后粘贴到下方文本框，首行为表头。</p>
        </div>
        <div class="supervisor-note-form" style="display:flex;flex-direction:column;gap:10px;">
          <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
            <a class="ghost" href="/api/posts/import-template.xlsx" target="_blank" rel="noopener">下载作品模板</a>
            <input id="postBulkImportFileInput" type="file" accept=".xlsx,.xls,.csv,text/csv" />
            <button class="ghost" id="postBulkImportFileSubmitBtn" type="button">上传文件导入</button>
          </div>
          <textarea id="postBulkImportInput" rows="12" placeholder="粘贴 Excel 复制内容（首行表头），列：平台 标题 作品类型 作品链接 账号ID 发布日期 文案 封面链接 播放量 点赞 评论 收藏 备注" style="width:100%;font-family:Menlo,Consolas,monospace;font-size:12px;">${escapeHtml(state.postBulkImportRaw || "")}</textarea>
          <div class="post-bulk-import-delimiter" style="display:flex;align-items:center;gap:12px;font-size:13px;color:#444;">
            <span>分隔符：</span>
            <label style="display:inline-flex;align-items:center;gap:4px;cursor:pointer;">
              <input type="radio" name="postBulkImportDelimiter" class="js-post-bulk-delimiter" data-value="tab" checked /> Tab
            </label>
            <label style="display:inline-flex;align-items:center;gap:4px;cursor:pointer;">
              <input type="radio" name="postBulkImportDelimiter" class="js-post-bulk-delimiter" data-value="comma" /> Comma
            </label>
          </div>
          <div class="supervisor-dialog-actions">
            <button class="ghost" id="postBulkImportCloseBtn" type="button">取消</button>
            <button class="primary" id="postBulkImportSubmitBtn" type="button">提交导入</button>
          </div>
          ${resultBlock}
        </div>
      </div>
    </div>
  `;
}


// ===== L2338-L2360 renderPostsTable =====
function renderPostsTable(rows) {
  if (!rows.length) return `<div class="empty">暂无作品数据</div>`;
  const actionButtons = (item) => {
    const buttons = [
      `<button class="ghost js-edit-post" data-id="${item.id}">编辑</button>`,
      `<button class="ghost danger js-delete-post" data-id="${item.id}">删除</button>`
    ];
    return `<div class="actions">${buttons.join("")}</div>`;
  };
  return `
    <div class="table-wrap">
      <table>
        <thead>
          <tr><th>封面</th><th>标题</th><th>账号</th><th>员工</th><th>平台</th><th>类型</th><th>发布时间</th><th>点赞</th><th>评论</th><th>互动更新时间</th><th>链接</th><th>操作</th></tr>
        </thead>
        <tbody>
          ${rows.map((item) => `<tr><td>${item.coverImageUrl ? `<button class="image-trigger image-trigger-inline js-open-image" data-src="${item.coverImageUrl}" type="button"><img class="cover-thumb" src="${item.coverImageUrl}" alt="封面" /></button>` : ""}</td><td>${item.title}</td><td>${item.accountName}</td><td>${item.employeeName}</td><td>${item.platform}</td><td>${item.postType}</td><td>${item.publishedAt}</td><td>${Number(item.likes || 0)}</td><td>${Number(item.comments || 0)}</td><td>${item.metricsUpdatedAt ? formatDate(item.metricsUpdatedAt) : "未抓取"}</td><td>${item.postUrl ? renderExternalLink(item.postUrl, "打开") : ""}</td><td>${actionButtons(item)}</td></tr>`).join("")}
        </tbody>
      </table>
    </div>
  `;
}


