// ===== L5446-L5453 deletePost =====
async function deletePost(id) {
  if (!window.confirm("确认删除该作品吗？")) return;
  await api(`/api/posts/${id}`, { method: "DELETE" });
  state.editingPostId = state.editingPostId === id ? "" : state.editingPostId;
  await loadData();
  renderApp();
}


// ===== L5474-L5562 submitPost / savePostSuggestion / refreshScopedMetrics / rollbackScopedMetrics =====
async function submitPost(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  const id = String(formData.get("id") || "");
  collectPostFormBuffer();

  // 提交前立即保存草稿（防止提交失败丢失数据）
  if (!id && typeof saveDraftNow === "function") {
    saveDraftNow("post", event.currentTarget);
  }

  if (state.postCoverFile) {
    formData.set("coverImage", state.postCoverFile, state.postCoverFile.name || "pasted-cover.png");
  }

  try {
    const result = await api(id ? `/api/posts/${id}` : "/api/posts", {
      method: id ? "PUT" : "POST",
      body: formData
    });

    // 提交成功后清除草稿
    if (!id && typeof clearDraftFromLocal === "function") {
      clearDraftFromLocal("post");
    }

    clearPendingPostCover();
    state._postFormBuffer = null;
    state.editingPostId = "";
    setFlash("success", id ? "作品已更新" : "作品已提交", "这条作品已经写入后台，主管端同步看板后会立刻看到。");
    await loadData();
    renderApp();

    if (result.metricsSyncError) {
      alert(`作品已保存，但互动数据暂未自动抓到：${result.metricsSyncError}`);
    }
  } catch (err) {
    // 提交失败时保留表单内容，不清空
    setFlash("error", "提交失败", err.message || "请检查网络连接后重试，已填写内容已自动保存。");
    throw err;
  }
}

async function savePostSuggestion(id) {
  const input = document.querySelector(`.post-board-suggestion-input[data-id="${id}"]`);
  if (!input) return;
  await api(`/api/posts/${id}/supervisor-suggestion`, {
    method: "PUT",
    body: JSON.stringify({
      supervisorSuggestion: input.value || ""
    })
  });
  setFlash("success", "主管建议已保存", "员工端这条作品会同步显示这条建议。");
  await loadData();
  renderApp();
}

async function refreshScopedMetrics() {
  const postIds = getScopedRefreshPostIds();
  if (!postIds.length) {
    alert("当前范围内没有可刷新的作品。");
    return;
  }
  try {
    const result = await api("/api/posts/refresh-metrics", {
      method: "POST",
      body: JSON.stringify({ postIds })
    });
    setFlash("success", "作品指标已刷新", `当前范围 ${result.requested || postIds.length} 条，成功 ${result.refreshed || 0} 条，失败 ${result.failed || 0} 条。`);
    await loadData();
    renderApp();
  } catch (error) {
    alert(error.message);
  }
}

async function rollbackScopedMetrics() {
  const postIds = getScopedRefreshPostIds();
  if (!postIds.length) {
    alert("当前范围内没有可回退的作品。");
    return;
  }

  if (!state.rollbackSnapshotDate) {
    alert("请先选择一个回退日期。");
    return;
  }

  if (!window.confirm(`确认将当前范围内作品的互动数据回退到 ${state.rollbackSnapshotDate} 的快照吗？`)) {
    return;
  }

  const password = window.prompt("请输入当前账号密码后再执行回退：", "");
  if (password === null) {
    return;
  }
  if (!String(password).trim()) {
    alert("未输入密码，已取消回退。");
    return;
  }

  try {
    const result = await api("/api/posts/rollback-metrics", {
      method: "POST",
      body: JSON.stringify({
        postIds,
        snapshotDate: state.rollbackSnapshotDate,
        password: String(password)
      })
    });
    await loadData();
    renderApp();
    const failedCount = Array.isArray(result.failed) ? result.failed.length : 0;
    alert(`已按 ${result.snapshotDate} 快照回退，成功 ${result.restored} 条，跳过 ${result.skipped} 条，失败 ${failedCount} 条。`);
  } catch (error) {
    alert(error.message);
  }
}

async function handleRefreshPostMetricsClick(button) {
  const id = button?.dataset?.id;
  if (!id) return;
  const post = state.posts.find((item) => item.id === id) || state.plazaPosts.find((item) => item.id === id);
  if (!post) {
    alert("找不到这条作品，可能已被删除。");
    return;
  }
  if (!post.postUrl) {
    alert("这条作品没有作品链接，无法抓取互动数据。");
    return;
  }
  if (button.disabled) return;
  button.disabled = true;
  const originalText = button.textContent;
  button.textContent = "刷新中...";
  try {
    await api(`/api/posts/${id}/fetch-metrics`, {
      method: "POST",
      body: JSON.stringify({ postUrl: post.postUrl })
    });
    setFlash("success", "互动数据已刷新", "已写入最新点赞、评论、收藏数据，并保存一份历史快照。");
    await loadData();
    renderApp();
  } catch (error) {
    alert(error?.message || "刷新失败，请稍后重试。");
    button.disabled = false;
    button.textContent = originalText;
  }
}

async function handleBatchRefreshFilteredPosts() {
  const filteredRows = typeof getFilteredPostsForMonitor === "function" ? getFilteredPostsForMonitor() : [];
  const eligible = filteredRows.filter((item) => item.postUrl);
  if (!eligible.length) {
    alert("当前筛选下没有可刷新的作品。");
    return;
  }
  if (!window.confirm(`确认批量刷新 ${eligible.length} 条作品互动数据吗？`)) {
    return;
  }
  const button = document.getElementById("batchRefreshFilteredPostsBtn");
  const originalText = button ? button.textContent : "";
  if (button) {
    button.disabled = true;
    button.textContent = "刷新中...";
  }
  try {
    const result = await api("/api/posts/refresh-metrics", {
      method: "POST",
      body: JSON.stringify({ postIds: eligible.map((item) => item.id) })
    });
    const results = Array.isArray(result?.results) ? result.results : [];
    const success = results.filter((entry) => entry && entry.success).length;
    const failed = results.filter((entry) => entry && !entry.success).map((entry) => ({
      id: entry.id,
      title: entry.title || state.posts.find((item) => item.id === entry.id)?.title || entry.id,
      message: entry.message || entry.reason || "抓取失败",
    }));
    state.postBatchRefreshFailures = failed;
    setFlash(failed.length ? "warn" : "success", "批量刷新完成", `已刷新 ${success}/${results.length || eligible.length} 条${failed.length ? `，失败 ${failed.length} 条，可查看明细并重试。` : ""}`);
  } catch (error) {
    alert(error?.message || "批量刷新失败，请稍后重试。");
  } finally {
    await loadData();
    renderApp();
  }
}

async function retryFailedPostRefreshes() {
  const failures = Array.isArray(state.postBatchRefreshFailures) ? state.postBatchRefreshFailures : [];
  const postIds = failures.map((entry) => entry.id).filter(Boolean);
  if (!postIds.length) return;
  const button = document.querySelector(".js-retry-failed-post-refresh");
  if (button) {
    button.disabled = true;
    button.textContent = "重试中...";
  }
  try {
    const result = await api("/api/posts/refresh-metrics", {
      method: "POST",
      body: JSON.stringify({ postIds })
    });
    const results = Array.isArray(result?.results) ? result.results : [];
    state.postBatchRefreshFailures = results.filter((entry) => entry && !entry.success).map((entry) => ({
      id: entry.id,
      title: entry.title || state.posts.find((item) => item.id === entry.id)?.title || entry.id,
      message: entry.message || entry.reason || "抓取失败",
    }));
    await loadData();
    renderApp();
  } catch (error) {
    alert(error?.message || "重试失败，请稍后再试。");
    if (button) {
      button.disabled = false;
      button.textContent = "重试失败项";
    }
  }
}

function getPostBulkImportRows(raw, delimiter) {
  return String(raw || "")
    .split(/\r?\n/)
    .map((line) => delimiter === "comma" ? line.split(",").map((cell) => cell.trim()).join("\t") : line)
    .filter((line) => String(line || "").trim());
}

async function submitPostBulkImport() {
  const textarea = document.getElementById("postBulkImportInput");
  const raw = textarea ? String(textarea.value || "") : "";
  const checkedDelimiterEl = document.querySelector(".js-post-bulk-delimiter:checked");
  const delimiter = checkedDelimiterEl?.dataset?.value === "comma" ? "comma" : "tab";
  const rows = getPostBulkImportRows(raw, delimiter);
  if (!rows.length) {
    alert("请粘贴需要导入的内容（首行表头）。");
    return;
  }
  state.postBulkImportRaw = raw;
  const submitBtn = document.getElementById("postBulkImportSubmitBtn");
  const originalText = submitBtn ? submitBtn.textContent : "";
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.textContent = "导入中...";
  }
  try {
    const result = await api("/api/posts/import-paste", {
      method: "POST",
      body: JSON.stringify({ rows })
    });
    state.postBulkImportResult = result || null;
    const failedCount = Number(result?.fail ?? result?.failed ?? 0);
    setFlash("success", "批量导入完成", `成功 ${Number(result?.success || 0)} 条，失败 ${failedCount} 条。`);
    await loadData();
    renderApp();
  } catch (error) {
    alert(error?.message || "批量导入失败，请稍后重试。");
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = originalText || "提交导入";
    }
  }
}

async function submitPostBulkImportFile() {
  const input = document.getElementById("postBulkImportFileInput");
  const [file] = input?.files || [];
  if (!file) {
    alert("请选择作品导入文件。");
    return;
  }
  const submitBtn = document.getElementById("postBulkImportFileSubmitBtn");
  const originalText = submitBtn ? submitBtn.textContent : "";
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.textContent = "上传中...";
  }
  try {
    const body = new FormData();
    body.set("file", file, file.name || "posts-import.xlsx");
    const result = await api("/api/posts/import", { method: "POST", body });
    state.postBulkImportResult = result || null;
    const failedCount = Number(result?.fail ?? result?.failed ?? 0);
    setFlash("success", "批量导入完成", `成功 ${Number(result?.success || 0)} 条，失败 ${failedCount} 条。`);
    await loadData();
    renderApp();
  } catch (error) {
    alert(error?.message || "作品文件导入失败，请检查模板后重试。");
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = originalText || "上传文件导入";
    }
  }
}

function closePostBulkImportDialog() {
  state.postBulkImportOpen = false;
  state.postBulkImportRaw = "";
  state.postBulkImportResult = null;
  renderApp();
}

function mountPostsMonitorPagination() {
  if (typeof setupPagination !== "function") return;
  setupPagination("postsMonitorPager", {
    pageSize: 20,
    fetchPage: async (page, pageSize, offset) => {
      const params = getPostMonitorDateRangeParams();
      params.set("limit", String(pageSize));
      params.set("offset", String(offset));
      if (state.postMonitorEmployeeFilter) params.set("employeeId", state.postMonitorEmployeeFilter);
      if (state.postMonitorTypeFilter) params.set("postType", state.postMonitorTypeFilter);
      if (state.postMonitorPlatformFilter) params.set("platform", state.postMonitorPlatformFilter);
      if (state.postMonitorAccountFilter) params.set("accountId", state.postMonitorAccountFilter);
      if (state.postMonitorSort) params.set("sort", state.postMonitorSort);
      const result = await api(`/api/posts?${params.toString()}`);
      const items = Array.isArray(result?.items) ? result.items : [];
      items.forEach((item) => {
        const idx = state.posts.findIndex((post) => post.id === item.id);
        if (idx >= 0) state.posts[idx] = item;
        else state.posts.push(item);
      });
      state.postTotal = Number(result?.total || items.length);
      return { items, total: state.postTotal };
    },
    renderItems: (items) => {
      const grid = document.getElementById("postsMonitorGrid");
      if (!grid) return;
      if (!items.length) {
        grid.innerHTML = `<div class="empty">这一天没有符合条件的帖子。</div>`;
        return;
      }
      grid.innerHTML = items.map(renderPostMonitorCard).join("");
    }
  });
}
